sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Convert the date to the server-side format (yyyy-MM-dd)
    var dateParts = newValue.split('/');
    var formattedDate = `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`; // Convert dd/MM/yyyy to yyyy-MM-dd

    // Call GlideAjax
    var ga = new GlideAjax('AjaxCheckDateSI'); // Replace with your processor name
    ga.addParam('sysparm_name', 'checkUserRequest'); // The function to call
    ga.addParam('sysparm_date', formattedDate); // Pass the formatted date
    ga.getXMLAnswer(function(answer) {
        if (answer === 'none') {
            console.log('No conflicts found.');
        } else if (answer) {
            console.error('Conflicting schedules: ' + answer);
			alert('Conflicting schedules. This date is not available.');
            // g_form.showFieldMsg('training_day', 'This date is not available.', 'error');
            g_form.clearValue('training_day');
        } else {
            console.error('Unexpected response from server.');
        }
    });
}


